//! Regression checks against NumPy/SciPy references (`common/data4.rs`,
//! generated by `gen/stats_ref4.py`) and exhaustive search.

mod common;
use common::data4::*;
use openstats_stats::model::{Data, DesignOptions};
use openstats_stats::regression::*;
use openstats_stats::report::Reportable;

fn close(got: f64, want: f64, rel: f64, what: &str) {
    let ok = if got == want {
        true
    } else if want == 0.0 {
        got.abs() <= rel
    } else {
        ((got - want) / want).abs() <= rel
    };
    assert!(ok, "{what}: got {got:e}, want {want:e}");
}

fn reg_data() -> Data {
    Data::new()
        .with_numeric("y", REG_Y.to_vec())
        .unwrap()
        .with_numeric("x1", REG_X1.to_vec())
        .unwrap()
        .with_numeric("x2", REG_X2.to_vec())
        .unwrap()
        .with_numeric("x3", REG_X3.to_vec())
        .unwrap()
        .with_numeric("x4", REG_X4.to_vec())
        .unwrap()
}

fn fit() -> RegressionFit {
    regress("y ~ x1 + x2 + x3 + x4", &reg_data(), &DesignOptions::default(), &RegressionOptions::default()).unwrap()
}

#[test]
fn coefficients_and_summary() {
    let f = fit();
    assert_eq!(f.coefficients.len(), 5);
    for (c, r) in f.coefficients.iter().zip(REG_COEF) {
        close(c.estimate, r.0, 1e-10, &c.name);
        close(c.std_err, r.1, 1e-10, &c.name);
        close(c.t, r.2, 1e-10, &c.name);
        close(c.p_value, r.3, 1e-9, &c.name);
        close(c.ci.lower, r.4, 1e-9, &c.name);
        close(c.ci.upper, r.5, 1e-9, &c.name);
        match c.vif {
            Some(v) => close(v, r.6, 1e-9, "vif"),
            None => assert!(r.6.is_nan()),
        }
    }
    let s = REG_SCALARS;
    close(f.s, s[0], 1e-10, "s");
    close(f.r2, s[1], 1e-10, "r2");
    close(f.r2_adj, s[2], 1e-10, "r2adj");
    close(f.r2_pred, s[3], 1e-9, "r2pred");
    close(f.press, s[4], 1e-10, "press");
    close(f.sse, s[5], 1e-10, "sse");
    close(f.f.unwrap(), s[6], 1e-10, "F");
    close(f.f_p.unwrap(), s[7], 1e-8, "Fp");
    close(f.diagnostics.durbin_watson, s[8], 1e-10, "dw");
    close(f.aic(), s[9], 1e-10, "aic");
    close(f.aicc(), s[10], 1e-10, "aicc");
    close(f.bic(), s[11], 1e-10, "bic");
    close(f.ssr, s[12], 1e-10, "ssr");
}

#[test]
fn diagnostics_match() {
    let f = fit();
    let d = &f.diagnostics;
    for (i, r) in REG_DIAG.iter().enumerate() {
        close(d.fitted[i], r.0, 1e-10, "fit");
        close(d.residuals[i], r.1, 1e-8, "resid");
        close(d.leverage[i], r.2, 1e-10, "h");
        close(d.standardized[i], r.3, 1e-9, "std");
        close(d.deleted[i], r.4, 1e-9, "del");
        close(d.cooks_d[i], r.5, 1e-9, "cook");
        close(d.dffits[i], r.6, 1e-9, "dffits");
    }
    let h: f64 = d.leverage.iter().sum();
    close(h, 5.0, 1e-12, "trace of hat matrix");
}

#[test]
fn anova_table() {
    let f = fit();
    let rows: Vec<_> = f.anova.iter().filter(|r| r.seq_ss.is_some()).collect();
    assert_eq!(rows.len(), 4);
    for (row, r) in rows.iter().zip(REG_TERMS) {
        close(row.seq_ss.unwrap(), r.0, 1e-9, &row.source);
        close(row.adj_ss, r.1, 1e-8, &row.source);
        close(row.p_value.unwrap(), r.2, 1e-8, &row.source);
    }
    let names: Vec<&str> = f.anova.iter().map(|r| r.source.as_str()).collect();
    assert_eq!(names.first(), Some(&"Regression"));
    assert_eq!(names.last(), Some(&"Total"));
    assert_eq!(f.anova.last().unwrap().df, 24);
    // Sequential SS of all terms add to the regression SS.
    let seq: f64 = rows.iter().map(|r| r.seq_ss.unwrap()).sum();
    close(seq, f.ssr, 1e-10, "sum of seq SS");
    assert!(f.lack_of_fit.is_none());
}

#[test]
fn prediction_intervals() {
    let f = fit();
    let new = Data::new()
        .with_numeric("x1", REG_PRED.iter().map(|r| r.0).collect())
        .unwrap()
        .with_numeric("x2", REG_PRED.iter().map(|r| r.1).collect())
        .unwrap()
        .with_numeric("x3", REG_PRED.iter().map(|r| r.2).collect())
        .unwrap()
        .with_numeric("x4", REG_PRED.iter().map(|r| r.3).collect())
        .unwrap();
    let p = f.predict(&new, 0.95).unwrap();
    assert_eq!(p.len(), 2);
    for (q, r) in p.iter().zip(REG_PRED) {
        close(q.fit, r.4, 1e-10, "fit");
        close(q.se_fit, r.5, 1e-9, "se");
        close(q.ci.lower, r.6, 1e-9, "ci lo");
        close(q.ci.upper, r.7, 1e-9, "ci hi");
        close(q.pi.lower, r.8, 1e-9, "pi lo");
        close(q.pi.upper, r.9, 1e-9, "pi hi");
    }
}

#[test]
fn lack_of_fit() {
    let d = Data::new().with_numeric("y", LOF_Y.to_vec()).unwrap().with_numeric("x", LOF_X.to_vec()).unwrap();
    let f = regress("y ~ x", &d, &DesignOptions::default(), &RegressionOptions::default()).unwrap();
    let l = f.lack_of_fit.as_ref().expect("replicated design");
    assert_eq!((l.df_lof as f64, l.df_pe as f64), (LOF_REF[0], LOF_REF[2]));
    close(l.ss_lof, LOF_REF[1], 1e-9, "ss lof");
    close(l.ss_pe, LOF_REF[3], 1e-9, "ss pe");
    close(l.f, LOF_REF[4], 1e-9, "F");
    close(l.p_value, LOF_REF[5], 1e-8, "p");
    assert!(f.anova.iter().any(|r| r.source == "Lack-of-Fit") && f.anova.iter().any(|r| r.source == "Pure Error"));
}

#[test]
fn factor_and_covariate() {
    let d = Data::new()
        .with_factor("A", FAC_A)
        .unwrap()
        .with_numeric("x", FAC_X.to_vec())
        .unwrap()
        .with_numeric("y", FAC_Y.to_vec())
        .unwrap();
    let f = regress("y ~ A + x", &d, &DesignOptions::default(), &RegressionOptions::default()).unwrap();
    assert_eq!(f.coefficients.len(), 4);
    for (c, r) in f.coefficients.iter().zip(FAC_COEF) {
        close(c.estimate, r.0, 1e-9, &c.name);
        close(c.std_err, r.1, 1e-9, &c.name);
    }
    let a = f.anova.iter().find(|r| r.source == "A").unwrap();
    assert_eq!(a.df, 2);
    close(a.adj_ss, FAC_ANOVA[0], 1e-9, "adj SS A");
    close(a.p_value.unwrap(), FAC_ANOVA[1], 1e-8, "p A");
    let x = f.anova.iter().find(|r| r.source == "x").unwrap();
    close(x.adj_ss, FAC_ANOVA[2], 1e-9, "adj SS x");
    close(x.p_value.unwrap(), FAC_ANOVA[3], 1e-8, "p x");
    close(f.sse, FAC_ANOVA[4], 1e-9, "sse");
    // Sum-to-zero coding changes the coefficients but not the fit.
    let opts =
        DesignOptions { default_contrast: openstats_stats::model::Contrast::SumToZero, ..DesignOptions::default() };
    let g = regress("y ~ A + x", &d, &opts, &RegressionOptions::default()).unwrap();
    close(g.sse, f.sse, 1e-10, "sse invariant to coding");
    close(g.r2_pred, f.r2_pred, 1e-9, "pred R2 invariant to coding");
}

#[test]
fn aliased_column_dropped() {
    let x2: Vec<f64> = REG_X1.iter().map(|v| 2.0 * v + 1.0).collect();
    let d = Data::new()
        .with_numeric("y", REG_Y.to_vec())
        .unwrap()
        .with_numeric("x1", REG_X1.to_vec())
        .unwrap()
        .with_numeric("x2", x2)
        .unwrap()
        .with_numeric("x3", REG_X3.to_vec())
        .unwrap();
    let f = regress("y ~ x1 + x2 + x3", &d, &DesignOptions::default(), &RegressionOptions::default()).unwrap();
    assert_eq!(f.aliased, vec!["x2".to_string()]);
    assert_eq!(f.coefficients.len(), 3);
    let g = regress("y ~ x1 + x3", &d, &DesignOptions::default(), &RegressionOptions::default()).unwrap();
    close(f.sse, g.sse, 1e-10, "sse");
}

#[test]
fn offset_and_no_intercept() {
    let d = reg_data();
    let f = regress("y ~ x1 + offset(0.5*x2)", &d, &DesignOptions::default(), &RegressionOptions::default()).unwrap();
    let yy: Vec<f64> = REG_Y.iter().zip(REG_X2).map(|(a, b)| a - 0.5 * b).collect();
    let g = fit_xy(&[("x1", REG_X1)], &yy, true, &RegressionOptions::default()).unwrap();
    close(f.coefficients[1].estimate, g.coefficients[1].estimate, 1e-10, "slope");
    close(f.sse, g.sse, 1e-10, "sse");
    // Fitted values include the offset.
    close(f.diagnostics.fitted[3], g.diagnostics.fitted[3] + 0.5 * REG_X2[3], 1e-10, "fitted");
    let h = regress("y ~ x1 - 1", &d, &DesignOptions::default(), &RegressionOptions::default()).unwrap();
    assert!(!h.intercept);
    let sxy: f64 = REG_X1.iter().zip(REG_Y).map(|(a, b)| a * b).sum();
    let sxx: f64 = REG_X1.iter().map(|a| a * a).sum();
    close(h.coefficients[0].estimate, sxy / sxx, 1e-12, "no-intercept slope");
    assert_eq!(h.anova.last().unwrap().df, 25);
}

#[test]
fn invalid_input() {
    let d = reg_data();
    assert!(regress("y ~ x1", &d, &DesignOptions::default(), &RegressionOptions { level: 1.0, ..Default::default() })
        .is_err());
    assert!(regress("y ~ nope", &d, &DesignOptions::default(), &RegressionOptions::default()).is_err());
    let tiny = Data::new().with_numeric("y", vec![1.0, 2.0]).unwrap().with_numeric("x", vec![1.0, 2.0]).unwrap();
    assert!(regress("y ~ x", &tiny, &DesignOptions::default(), &RegressionOptions::default()).is_err());
    assert!(fit().predict(&Data::new().with_numeric("x1", vec![1.0]).unwrap(), 0.95).is_err());
}

#[test]
fn report_renders() {
    let f = fit();
    let r = f.to_report("Regression");
    r.validate().unwrap();
    let text = r.render_text();
    for key in ["Analysis of Variance", "Model Summary", "Coefficients", "Durbin-Watson"] {
        assert!(text.contains(key), "missing {key}");
    }
    assert_eq!(r.charts().len(), 4);
    let json = r.to_json();
    assert_eq!(openstats_stats::report::SessionReport::from_json(&json).unwrap().tables().len(), r.tables().len());
}

// ---------------------------------------------------------------- selection

fn bs_cols() -> Vec<(String, Vec<f64>)> {
    [BS_X1, BS_X2, BS_X3, BS_X4, BS_X5, BS_X6, BS_X7]
        .iter()
        .enumerate()
        .map(|(i, c)| (format!("x{}", i + 1), c.to_vec()))
        .collect()
}

fn bs_data() -> Data {
    let mut d = Data::new().with_numeric("y", BS_Y.to_vec()).unwrap();
    for (n, c) in bs_cols() {
        d = d.with_numeric(&n, c).unwrap();
    }
    d
}

#[test]
fn best_subsets_matches_exhaustive_search() {
    let cols = bs_cols();
    let refs: Vec<(&str, &[f64])> = cols.iter().map(|(n, c)| (n.as_str(), c.as_slice())).collect();
    let res = best_subsets(&refs, BS_Y, &SubsetOptions::default(), &RegressionOptions::default()).unwrap();
    assert_eq!(res.models.len(), BS_BEST.len());
    for (m, r) in res.models.iter().zip(BS_BEST) {
        assert_eq!(m.size, r.0);
        let mask: u32 = m.vars.iter().map(|&v| 1u32 << v).sum();
        assert_eq!(mask, r.1, "size {}", r.0);
        close(m.sse, r.2, 1e-9, "sse");
        close(m.r2, r.3, 1e-10, "r2");
        close(m.r2_adj, r.4, 1e-9, "adj");
        close(m.cp, r.5, 1e-8, "cp");
    }
    // The full model has Cp = number of coefficients.
    let full = res.models.iter().rev().find(|m| m.size == 7).unwrap();
    close(full.cp, 8.0, 1e-9, "Cp of full model");
}

#[test]
fn best_subsets_options() {
    let cols = bs_cols();
    let refs: Vec<(&str, &[f64])> = cols.iter().map(|(n, c)| (n.as_str(), c.as_slice())).collect();
    let o =
        SubsetOptions { min_size: 2, max_size: Some(3), n_best: 1, force_in: vec!["x7".into()], ..Default::default() };
    let res = best_subsets(&refs, BS_Y, &o, &RegressionOptions::default()).unwrap();
    assert_eq!(res.models.iter().map(|m| m.size).collect::<Vec<_>>(), vec![2, 3]);
    assert!(res.models.iter().all(|m| m.names.contains(&"x7".to_string())));
    // Compare with the best forced model by brute force over the other six.
    let mut best2 = f64::INFINITY;
    for j in 0..6 {
        let f = fit_xy(&[(refs[j].0, refs[j].1), refs[6]], BS_Y, true, &RegressionOptions::default()).unwrap();
        best2 = best2.min(f.sse);
    }
    close(res.models[0].sse, best2, 1e-9, "forced best of size 2");
    assert!(best_subsets(
        &refs,
        BS_Y,
        &SubsetOptions { force_in: vec!["zz".into()], ..Default::default() },
        &RegressionOptions::default()
    )
    .is_err());
    let r = res.to_report("Best subsets");
    r.validate().unwrap();
}

#[test]
fn best_subsets_no_intercept_and_aliased() {
    let cols = bs_cols();
    let mut refs: Vec<(&str, &[f64])> = cols.iter().take(4).map(|(n, c)| (n.as_str(), c.as_slice())).collect();
    let dup: Vec<f64> = BS_X1.iter().map(|v| 3.0 * v).collect();
    refs.push(("dup", &dup));
    let res = best_subsets(
        &refs,
        BS_Y,
        &SubsetOptions { intercept: false, n_best: 1, ..Default::default() },
        &RegressionOptions::default(),
    )
    .unwrap();
    assert_eq!(res.excluded, vec!["dup".to_string()]);
    for size in 1..=4usize {
        let mut best = f64::INFINITY;
        for mask in 1u32..16 {
            if mask.count_ones() as usize != size {
                continue;
            }
            let sub: Vec<(&str, &[f64])> = (0..4).filter(|j| mask >> j & 1 == 1).map(|j| refs[j]).collect();
            best = best.min(fit_xy(&sub, BS_Y, false, &RegressionOptions::default()).unwrap().sse);
        }
        close(res.models.iter().find(|m| m.size == size).unwrap().sse, best, 1e-9, "no-intercept best");
    }
}

fn run(opts: StepwiseOptions) -> (Vec<(u8, usize)>, Vec<usize>) {
    let r = stepwise(
        "y ~ x1+x2+x3+x4+x5+x6+x7",
        &bs_data(),
        &DesignOptions::default(),
        &opts,
        &RegressionOptions::default(),
    )
    .unwrap();
    let idx = |l: &str| l[1..].parse::<usize>().unwrap() - 1;
    let steps = r.steps.iter().map(|s| (u8::from(s.action == StepAction::Added), idx(&s.term))).collect();
    let mut sel: Vec<usize> = r.selected.iter().map(|l| idx(l)).collect();
    sel.sort_unstable();
    // The returned fit is the fit of the selected terms.
    assert_eq!(r.fit.coefficients.len(), sel.len() + 1);
    r.to_report("step").validate().unwrap();
    (steps, sel)
}

fn check(i: usize, got: (Vec<(u8, usize)>, Vec<usize>)) {
    let (steps, sel) = STEP_REF[i];
    assert_eq!(got.0, steps.to_vec(), "steps of case {i}");
    assert_eq!(got.1, sel.to_vec(), "selection of case {i}");
}

#[test]
fn stepwise_matches_independent_implementation() {
    let mut o = StepwiseOptions::new(StepMethod::Stepwise);
    check(0, run(o.clone()));
    o.criterion = StepCriterion::PValue { alpha_enter: 0.10, alpha_remove: 0.20 };
    check(1, run(o));
    check(2, run(StepwiseOptions::new(StepMethod::Forward)));
    check(3, run(StepwiseOptions::new(StepMethod::Backward)));
    for (i, (m, c)) in [
        (StepMethod::Forward, StepCriterion::Aic),
        (StepMethod::Forward, StepCriterion::Bic),
        (StepMethod::Forward, StepCriterion::Aicc),
        (StepMethod::Backward, StepCriterion::Bic),
    ]
    .into_iter()
    .enumerate()
    {
        let mut o = StepwiseOptions::new(m);
        o.criterion = c;
        check(4 + i, run(o));
    }
}

#[test]
fn stepwise_force_and_validation() {
    let mut o = StepwiseOptions::new(StepMethod::Stepwise);
    o.force_in = vec!["x4".into()];
    let r =
        stepwise("y ~ x1+x2+x3+x4+x5+x6+x7", &bs_data(), &DesignOptions::default(), &o, &RegressionOptions::default())
            .unwrap();
    assert!(r.selected.contains(&"x4".to_string()));
    assert!(r.steps.iter().all(|s| !(s.term == "x4" && s.action == StepAction::Removed)));
    o.force_in = vec!["q".into()];
    assert!(stepwise("y ~ x1+x2", &bs_data(), &DesignOptions::default(), &o, &RegressionOptions::default()).is_err());
    let mut bad = StepwiseOptions::new(StepMethod::Stepwise);
    bad.criterion = StepCriterion::PValue { alpha_enter: 0.3, alpha_remove: 0.1 };
    assert!(stepwise("y ~ x1+x2", &bs_data(), &DesignOptions::default(), &bad, &RegressionOptions::default()).is_err());
}

#[test]
fn stepwise_hierarchy() {
    // y depends on A and B only through an interaction-free additive model;
    // the interaction may enter only after both margins are in the model.
    let a: Vec<f64> = (0..40).map(|i| f64::from(i % 5)).collect();
    let b: Vec<f64> = (0..40).map(|i| f64::from((i * 7) % 11)).collect();
    let y: Vec<f64> =
        a.iter().zip(&b).enumerate().map(|(i, (p, q))| 1.0 + 2.0 * p * q + ((i * 37) % 13) as f64 * 0.05).collect();
    let d = Data::new().with_numeric("y", y).unwrap().with_numeric("A", a).unwrap().with_numeric("B", b).unwrap();
    let mut o = StepwiseOptions::new(StepMethod::Forward);
    o.criterion = StepCriterion::PValue { alpha_enter: 0.05, alpha_remove: 0.05 };
    let r = stepwise("y ~ A*B", &d, &DesignOptions::default(), &o, &RegressionOptions::default()).unwrap();
    let pos = |t: &str| r.steps.iter().position(|s| s.term == t);
    if let Some(pi) = pos("A*B") {
        assert!(
            pos("A").is_some_and(|p| p < pi) && pos("B").is_some_and(|p| p < pi),
            "margins must precede the interaction: {:?}",
            r.steps
        );
    }
    assert!(r.selected.contains(&"A*B".to_string()));
    o.hierarchical = false;
    let r2 = stepwise("y ~ A*B", &d, &DesignOptions::default(), &o, &RegressionOptions::default()).unwrap();
    assert_eq!(r2.steps[0].term, "A*B");
}
